@kbench.task(name='chronos-r2-tree4-c-qwen-low-s02-v1')
def experiment_c(llm):
    if llm.model != MODEL:
        raise ValueError('unexpected selected model')
    llm.client = llm.client.with_options(max_retries=0)
    _policy = CONTRACT['transport_policy']
    _waits = dict(schema=_policy['schema'], count=0, seconds=0)
    _waits_path = OUTPUT / 'transient_waits.json'
    _waits_path.write_text(json.dumps(_waits, sort_keys=True) + '\n')
    _original_respond = llm.respond
    def _respond(**kwargs):
        waited, delay = 0, _policy['initial_delay_seconds']
        while True:
            try:
                return _original_respond(**kwargs)
            except Exception as error:
                if type(error).__name__ not in _policy['wait_on']:
                    raise
                remaining = _policy['max_wait_seconds_per_call'] - waited
                if remaining <= 0:
                    raise
                pause = min(delay, remaining)
                print('TRANSIENT', type(error).__name__, 'waiting', pause, 's', flush=True)
                time.sleep(pause)
                waited += pause
                _waits['count'] += 1
                _waits['seconds'] += pause
                _waits_path.write_text(json.dumps(_waits, sort_keys=True) + '\n')
                delay = min(delay * 2, _policy['max_delay_seconds'])
    llm.respond = _respond
    stopped = None
    try:
        protocol.engine.run_jobs(kbench, llm, FIXTURES, JOBS, OUTPUT, CONTRACT['ceiling_usd'])
    except Exception as error:
        # Do not raise: errored Kaggle tasks can discard paid raw evidence.
        stopped = repr(error)
    events, invalid_lines = parse_jsonl_best_effort(EVIDENCE.read_bytes() if EVIDENCE.exists() else b'')
    report, audit_error = None, None
    if invalid_lines:
        audit_error = 'malformed raw JSONL; inspect preserved evidence'
    else:
        try:
            report = auditor.audit(_reconciled_events(EVIDENCE.read_bytes()), MODEL, SELECTION, require_complete=False, expected_job_ids=set(CONTRACT['expected_job_ids']))
        except Exception as error:
            audit_error = repr(error)
    raw = raw_event_summary(events, invalid_json_lines=len(invalid_lines))
    terminal = dict(schema='chronos.experiment-c-hosted-terminal.v1', task=TASK,
        contract_sha256=CONTRACT['contract_sha256'], status='complete' if report and report['complete'] and not stopped else 'stopped',
        stopped_early=stopped, audit_error=audit_error, audit=report, raw_accounting=raw, cost_reconciliation=CONTRACT['cost_reconciliation'])
    (OUTPUT / 'terminal.json').write_text(json.dumps(terminal, indent=2, sort_keys=True) + '\n')
    print('EXPERIMENT_C_TERMINAL', json.dumps(terminal, sort_keys=True), flush=True)
